import{_ as a,o as _,c as e,a3 as t}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/79-10-当焦虑——回避型伴侣的冲突成为常态.md","filePath":"books/attached/79-10-当焦虑——回避型伴侣的冲突成为常态.md","lastUpdated":1794298621000}'),o={name:"books/attached/79-10-当焦虑——回避型伴侣的冲突成为常态.md"};function r(l,p,i,s,n,d){return _(),e("div",null,[...p[0]||(p[0]=[t('<h2 id="_10-当焦虑——回避型伴侣的冲突成为常态" tabindex="-1">10 当焦虑——回避型伴侣的冲突成为常态 <a class="header-anchor" href="#_10-当焦虑——回避型伴侣的冲突成为常态" aria-label="Permalink to &quot;10 当焦虑——回避型伴侣的冲突成为常态&quot;">​</a></h2><ul><li><p>克莱（Clay）和汤姆原本正在享受纪念日的浪漫晚餐。克莱深情地望着汤姆，汤姆冷不丁冒出来一句：“你他妈的在看什么？别盯着我了，真让人恼火！”克莱听了，强压住心中的怒气，没有直接起身走掉。他沉默不语，两人一言不发地结束了这顿晚餐。</p></li><li><p>在加里（Gary）和苏（Sue）的危地马拉之行中，加里总是把苏甩在后面，完全不愿并排走着互相照应。还不时地暗讽苏，说她又懒又笨才走得那么慢。</p></li><li><p>帕特（Pat）答应丈夫，在亲热的时候不给任何回应，事后丈夫说，“简直妙不可言，最奇妙的地方在于，就像在和一个陌生的女人做爱，简直太刺激了！”帕特听完，心里翻江倒海。</p></li></ul><p>在上一章，我们探讨了焦虑——回避型亲密关系中的冲突，以及一些可能的解决方法。但是在某些情况下，不管多么努力，事情都无法挽回，而且两种依恋风格的人的过多纠缠只会两败俱伤。更糟糕的是，很多回避型和焦虑型的情侣，还会促使对方不断恶化，冲突与伤害会成为生活的常态。</p><p>一般我们认为，只有受虐狂式的、同情心泛滥的人才会一再地容忍对方，他们宁可痛苦也不愿分手，可能他们就甘愿这样！还有的人认为，这类人是将糟糕的童年体验，再现到了成人阶段。玛莎（Marsha）和克雷格（Craig）的故事，就很好地印证了这个猜想。我们在为这本书收集个案的事后，采访到了31岁的玛莎，她非常外向，很乐意将自己的故事分享给我们，即使很多记忆对她来说，都是难以启齿而伤痛的，她也并无顾虑。她说将自己的故事分享出来，是想帮助更多有着共同遭遇的女性。她想告诉她们，从一段支离破碎的感情中逃离出来，到别处找到幸福是完全可能的。玛莎来自一个幸福美满的家庭，而在与克雷格的感情结束之后，她也找到了一个对她无微不至的男人。要说玛莎生活中有什么“瑕疵”，那可能就是焦虑型的她，遇到了回避型的克雷格吧。我们在第5章也提到过，焦虑型与回避型的人之间，有着致命的吸引力，而一旦走到一起，却又难以为继。而玛莎的故事就清楚地演绎了一段极致的焦虑——回避型关系，以及关系结束之后所需产生的巨大心理困境。</p><p>虽然曲折，但玛莎的故事终究结尾美满，我们将此总结成三点：首先，依恋的力量不可小觑；其次，即使是心智很健康的人，也可能遭遇糟糕的感情状况；最后，遇到此类情况的人们也应该相信，鼓起勇气结束一段感情，自己也有能力找到更好的生活。</p><p>我是在念大学的时候遇到克雷格的，他脸上有点儿痘，显得帅气可爱，总之是我喜欢的长相。不仅如此，他当时是我主修的物理学科的助教，学术水平远超那时候的我，所以当时在我眼里，他是闪闪发光的。不过，刚认识他的时候，他就已经有一些让我困惑和沮丧的行为。</p><p>他第一次约我出去，我以为那是一次约会，精心打扮出席，却发现只是跟他一票朋友的聚会而已。我想换做任何一个女孩接到这样的邀请，都会产生和我一样的想法。但我还是用最大的善意揣摩他，心想我是不是对他有什么误会。没过多久，他单独约我出去了，因此我更确定了第一次的“约会”事件，是我对他的误解。</p><p>一个月以后，我在克雷格田径训练的时候去给他探班鼓劲，想给他一个惊喜。没想到克雷格非但没有对我的支持表示感激，而且直接无视了我。他和朋友在一起，连招呼都没跟我打。除了感觉自己让他丢脸了，我都不知道还能做什么。</p><p>事后，我就克雷格的所作所为向他质问。他的回答是：“玛莎，我并不认为我的队友需要知道我俩是一对儿。”他的话让我十分愤怒，眼泪止不住地掉了下来。但随后他就拥抱并亲吻我，我心一软也就不生气了。自那以后，虽然克雷格并没有公开我俩的关系，但我很明显地表现出了跟他的恋爱关系。</p><p>然而，这并不是我最后一次发现，我们两个似乎并没有达成确定恋爱的共识。我们交往几个月后，我自以为进展还算顺利。为了令这段关系更加清晰稳固，我告诉前男友，表示以后别再见面了。在此之前，我们还会偶尔有些交集。当我把这事告诉克雷格的时候，他的反应令我措手不及：“你干吗跟前任说这个呢？现在还为时过早，我们现在的关系还代表不了什么。”</p><p>又经过了几个月的相处，克雷格似乎终于承认了我们的关系。他搬到了一间大床公寓中，还提议让我搬去和他一起住。我觉得这是他对我的承诺，于是欣然答应了。周围的人都非常看好我们，他们都对克雷格的印象很不错。而与他交情比较浅的朋友，更是觉得克雷格是个非常好相处的人。但事实上，我与克雷格共同生活的日子，遭遇了情绪上的巨大跌宕起伏，几乎每天都在眼泪中度过。</p><p>首先，克雷格老是拿我和前女友金杰（Ginger）作比较。在克雷格看来，金杰聪明貌美、风趣精明，一切都堪称完美。他们甚至至今保持联系，这让我非常难以接受，并且开始怀疑自己。每当他夸赞金杰的时候，还会顺带贬低我，特别是在涉及我的学术能力问题时，这种比较尤为频繁。他在我工作速度有限的时候会贬低我，这让我难过得要死。但我深知自己没那么糟，好歹也是常春藤联盟高校的学生啊，所以事后也就没太在意。</p><p>而另一件事，让我对自己的外表也产生了自卑感。我开始对自己的外貌产生不安全感，特别是克雷格会对我的一点点赘肉，或者其他的小瑕疵都能无限放大，喋喋不休几个星期。他第一次在洗澡时看到我的裸体，对我的评价是：“一个胸很大的侏儒。”我把他的负面评价牢记在了心里，有时候甚至因此看不起自己。一旦自己吃太多感觉长胖了，就会问他为什么还愿意和一个那么丑的人亲热。很多男朋友，或者说大多数人，在面对这样一个自我贬低的人时，都会做出一些鼓励性的回应，比如说：“玛莎，你怎么会这么想呢？你其实很美！”</p><p>而克雷格会直接回答：“因为想做爱的时候，你刚好在旁边啊。”他似乎完全不考虑自己的言语多么伤人，也有可能他意识到了，只是觉得自己在陈述事实。</p><p>我曾试着告诉他，他有些做法非常伤人，甚至有几次直接向他表示，他的言行似乎显示出了一些情商上的障碍。而他总是对我的话左耳进右耳出。有时候我会觉得自己完全左右不了他的行为，应该考虑一下跟他分手。但我从来没有付诸过实践。因为他会告诉我，他是爱我的，我也会通过相处，让他承认我的重要性。</p><p>他到底爱我吗？或许是爱的吧。他几乎每天都会告诉我，自己是爱我的。我会不断回味和评估他的行为，毕竟他成长于一个并不健康的家庭环境，所以这一切都情有可原。他父亲非常强势，对他妈妈很不好。因此，我开始将他的行为合理化，因为他“不知道如何做得更好”。如果他学会了正确的言行，我盼望着、构想着、期待着他或许会养成好的习惯，产生良性的转变。</p><p>而我的这些想法，也需要自己对他更加容忍。比如将克雷格的极度强势，都归咎于他父亲的影响。我们所做的事都依着他的意愿，他几乎主导者所有事情的决定权。我们看什么电影，做什么饭菜，都由他决定。在知道我对房间的装修品位非常看重的情况下，他竟然坚持要将NBA球星沙奎尔·奥尼尔（Shaquille O&#39;Neal）的海报挂在墙上，挂在客厅的墙上！</p><p>由于我对克雷格对待我的恶劣方式，或者说我纵容他对待我的恶行，感到非常羞耻，所以我从来不跟朋友谈及他的所作所为。而跟他朋友待在一起的时光，也没好到哪里去。我平时比较内向，有一次跟他的一些朋友出去玩时，我试图挑起一个话题来打破冷场。而他直接插话说道：“嘿，大家听着！我的‘天才’女朋友要发表意见了！”还有一次在海滩上，我叫他把毛巾递给我，他直接在众目睽睽之下对我吼道：“你就用太阳晾干吧！”这仅仅是两个例子而已，我遇到的类似情况数不胜数。我一直向他抗议这种对我说话的方式，不过最后反而是我妥协了。</p><p>在我们的关系中，有一点非常重要，就是因为这一点，我才容忍了他，以及这段糟糕的关系那么久，那就是他的确是个非常深情的人。我们常常拥抱，而且每晚相拥入眠。而这种深情，让我感觉性生活是很和谐的。其实克雷格在我交的男朋友中，是发生关系最少的一个，但是相拥的舒适，很大程度上减少了我被拒绝的伤痛感。</p><p>我总是在脑海里为他辩解，但随着时间推移，自己的思维方式也变得越发扭曲。我会跟自己说，“没有完美的亲密关系，要想跟克雷格好好地生活，你就必须得做出一些妥协。”在一起好几年以后，我感觉自己不能再浪费青春，应该考虑结婚了。在我向他提议之后，他的回答非常混蛋，比如说：“跟你结婚就意味着我以后再也不能和二十几岁的女孩子睡觉了！”即便如此，我还是很想嫁给他。</p><p>决定结婚算是一件我逼着克雷格做的事了，而他答应以后，我就知道了这是个错误。从他开口说出“那就去吧”这句话开始，结婚的噩梦就开始了。他挑的戒指很不走心，上面的宝石都快掉了，这难道还不足以预兆我后面的遭遇吗？</p><p>我们在巴黎度的蜜月也非常糟糕。我们时刻都待在一起，深刻地感受到了克雷格对我事事限制。本来我们有大把的时间可以享受，克雷格却总是把每件事情都弄得很煎熬。他抱怨酒店的服务，还在我不小心上错了地铁线的时候，对我大发雷霆。那一次旅行让我深感水深火热。当克雷格对我破口大骂的那一刻，我意识到自己根本无力改变他。后来我们回到家，家人问到我的蜜月旅行，我实在没有勇气告诉他们，这简直是一场灾难。我用很没底气还带点悲伤的声音回答道：“挺好的。”这恐怕是对一次蜜月旅行最伤感的描述了。</p><p>即使自己感觉深陷泥沼，却还是没办法下定决心全身而退。我多次鼓起勇气决心分开，克雷格却觉得自己咬定了我，根本有恃无恐。我甚至开始陷入一种幻想，期待他会抛弃我爱上别人，因为我觉得自己永远也没办法鼓起勇气先离开他。不过所幸，克雷格还是触及到了我的底线。我一而再再而三地跟他提出离婚，他总是央求我留下，而有一次他向我保证，假使下一次再惹得我想离婚，他就不会再挽留了。他说出这句话我感觉如释重负，等到下一次我忍无可忍向他提出离婚时，他爽快答应了。我付了10000美元的违约金，因为之前我们签了一份共同购买房产的协议。不过现在看来，这是我花得最值的一笔钱了。</p><p>我们离婚倒是进展得比较顺利，后来我们也保持着联系。当自己不再和他一起生活，与他相处的日子反倒轻松了很多，当然我们也并不常常待在一起。他的确是个风趣、深情而有魅力的人，一旦他说要出什么伤人的话，我就直接站起来走掉。</p><p>非常幸运的是，玛莎后来遇到了对的人，开始了幸福的生活。跟新的伴侣开始以后，玛莎换了一份收入更高的工作，也发展了很多新的爱好，再也没有遭遇克雷格带给她的那种情感折磨。</p>',25)])])}const u=a(o,[["render",r]]);export{h as __pageData,u as default};
